  1	// Minimal server-side MCP (Model Context Protocol) client over the streamable-HTTP
  2	// transport. Enough to connect to a server, complete the `initialize` handshake, and
  3	// enumerate / call its tools. Used by the MCP test probe (list tools) and, later, by
  4	// the agent runtime (call tools). Read-only here apart from the explicit tools/call.
  5	
  6	const PROTOCOL_VERSION = "2024-11-05";
  7	
  8	export interface McpTool {
  9	  name: string;
 10	  description?: string;
 11	  inputSchema?: unknown;
 12	}
 13	
 14	interface JsonRpcResponse {
 15	  result?: {
 16	    serverInfo?: { name?: string };
 17	    tools?: McpTool[];
 18	    content?: unknown;
 19	    isError?: boolean;
 20	  };
 21	  error?: { message?: string };
 22	}
 23	
 24	/** Parse a JSON-RPC response that may arrive as plain JSON or an SSE `data:` frame. */
 25	function parseRpc(text: string): JsonRpcResponse | null {
 26	  const t = text.trim();
 27	  if (t.startsWith("{")) {
 28	    try {
 29	      return JSON.parse(t) as JsonRpcResponse;
 30	    } catch {
 31	      return null;
 32	    }
 33	  }
 34	  for (const line of t.split("\n")) {
 35	    const l = line.trim();
 36	    if (l.startsWith("data:")) {
 37	      try {
 38	        return JSON.parse(l.slice(5).trim()) as JsonRpcResponse;
 39	      } catch {
 40	        /* keep scanning */
 41	      }
 42	    }
 43	  }
 44	  return null;
 45	}
 46	
 47	interface PostResult {
 48	  ok: boolean;
 49	  status: number;
 50	  json: JsonRpcResponse | null;
 51	  sessionId: string | undefined;
 52	}
 53	
 54	async function post(url: string, token: string, body: unknown, sessionId?: string): Promise<PostResult> {
 55	  const headers: Record<string, string> = {
 56	    "Content-Type": "application/json",
 57	    Accept: "application/json, text/event-stream",
 58	  };
 59	  if (token) headers["Authorization"] = `Bearer ${token}`;
 60	  if (sessionId) headers["Mcp-Session-Id"] = sessionId;
 61	  const res = await fetch(url, {
 62	    method: "POST",
 63	    headers,
 64	    body: JSON.stringify(body),
 65	    redirect: "manual",
 66	    signal: AbortSignal.timeout(12_000),
 67	  });
 68	  const newSession = res.headers.get("Mcp-Session-Id") ?? sessionId;
 69	  let json: JsonRpcResponse | null = null;
 70	  if (res.ok) json = parseRpc(await res.text());
 71	  return { ok: res.ok, status: res.status, json, sessionId: newSession };
 72	}
 73	
 74	export interface McpConnectResult {
 75	  ok: boolean;
 76	  serverName?: string;
 77	  tools?: McpTool[];
 78	  error?: string;
 79	}
 80	
 81	/** Connect, run the initialize handshake, and list the server's tools. */
 82	export async function connectAndListTools(url: string, token: string): Promise<McpConnectResult> {
 83	  const init = await post(url, token, {
 84	    jsonrpc: "2.0",
 85	    id: 1,
 86	    method: "initialize",
 87	    params: { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: "aria-sourcing", version: "1.0" } },
 88	  });
 89	  if (!init.ok) return { ok: false, error: `MCP server responded ${init.status}.` };
 90	  if (!init.json?.result) return { ok: false, error: init.json?.error?.message ?? "No valid MCP initialize response." };
 91	
 92	  const serverName = init.json.result.serverInfo?.name ?? "MCP server";
 93	  const session = init.sessionId;
 94	
 95	  // Acknowledge initialization (best-effort; some servers require it before tools/list).
 96	  try {
 97	    await post(url, token, { jsonrpc: "2.0", method: "notifications/initialized" }, session);
 98	  } catch {
 99	    /* ignore — not all servers need this */
100	  }
101	
102	  // List tools (best-effort: a server may not expose tools).
103	  let tools: McpTool[] = [];
104	  try {
105	    const list = await post(url, token, { jsonrpc: "2.0", id: 2, method: "tools/list", params: {} }, session);
106	    tools = (list.json?.result?.tools ?? []).map((t) => ({
107	      name: t.name,
108	      description: t.description,
109	      inputSchema: t.inputSchema,
110	    }));
111	  } catch {
112	    /* tools optional */
113	  }
114	
115	  return { ok: true, serverName, tools };
116	}
117	
118	/** Call a single tool on the server. Returns the tool result content or an error. */
119	export async function callMcpTool(
120	  url: string,
121	  token: string,
122	  toolName: string,
123	  args: Record<string, unknown>,
124	): Promise<{ ok: boolean; content?: unknown; error?: string }> {
125	  const init = await post(url, token, {
126	    jsonrpc: "2.0",
127	    id: 1,
128	    method: "initialize",
129	    params: { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: "aria-sourcing", version: "1.0" } },
130	  });
131	  if (!init.ok || !init.json?.result) return { ok: false, error: init.json?.error?.message ?? "MCP initialize failed." };
132	  const session = init.sessionId;
133	  try {
134	    await post(url, token, { jsonrpc: "2.0", method: "notifications/initialized" }, session);
135	  } catch {
136	    /* ignore */
137	  }
138	  const call = await post(
139	    url,
140	    token,
141	    { jsonrpc: "2.0", id: 2, method: "tools/call", params: { name: toolName, arguments: args } },
142	    session,
143	  );
144	  if (!call.json?.result) return { ok: false, error: call.json?.error?.message ?? "Tool call returned no result." };
145	  return { ok: !call.json.result.isError, content: call.json.result.content };
146	}

