14	/**
15	 * Connection test for a registered MCP (Model Context Protocol) server. Runs the MCP
16	 * `initialize` JSON-RPC handshake against the server's HTTP endpoint and reports
17	 * whether it answered as a valid MCP server. Admin-gated (manage_tools) in live mode;
18	 * the Bearer token is resolved server-side from the key vault and never returned.
19	 */
20	const McpTestSchema = z.object({
21	  url: z.string().url().max(500),
22	  apiKeyId: z.string().uuid().optional(),
23	});
24	
25	export async function POST(req: NextRequest) {
26	  const prodBlock = prodFailClosed();
27	  if (prodBlock) return prodBlock;
28	
29	  const rl = checkRateLimit(rateLimitKey(req, "mcp-test"), { windowMs: 60_000, max: 20 });
30	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
31	
32	  let token = "";
33	  if (supabaseEnabled) {
34	    const supabase = await getServerSupabase();
35	    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
36	    const {
37	      data: { user },
38	    } = await supabase.auth.getUser();
39	    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
40	    const { data: role } = await supabase.rpc("current_profile_role");
41	    if (!can(role as Role, "manage_tools")) {
42	      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
43	    }
44	  } else if (demoLoginEnabled) {
45	    // Public demo (no Supabase): require the signed admin/admin session cookie so
46	    // this route isn't reachable anonymously (mirrors the hermes/chat cost gate).
47	    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
48	      return NextResponse.json({ ok: false, error: "Sign in to use this tool." }, { status: 401 });
49	    }
50	  }
51	
52	  const validated = await validateBody(req, McpTestSchema, { maxBytes: 5_000 });
53	  if (!validated.ok) return validated.response;
54	  const { url, apiKeyId } = validated.data;
55	
56	  // Only http(s); never follow redirects (SSRF hardening). The URL is admin-entered.
57	  let parsed: URL;
58	  try {
59	    parsed = new URL(url);
60	  } catch {
61	    return NextResponse.json({ ok: false, error: "Invalid URL." });
62	  }
63	  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") {
64	    return NextResponse.json({ ok: false, error: "Only http(s) MCP endpoints are supported." });
65	  }
66	
67	  // SSRF guard: block private/loopback/link-local/metadata hosts (and DNS-rebinding)
68	  // before the server ever dials the admin-entered URL.
69	  const guard = await assertPublicUrl(url);
70	  if (!guard.ok) {
71	    return NextResponse.json({ ok: false, error: guard.reason ?? "URL blocked." }, { status: 400 });
72	  }
73	
74	  // Resolve the Bearer token from the vault if one was linked, scoped to the
75	  // caller's workspace (see resolveVaultSecret in @/lib/ai/vault-secret.ts).
76	  if (apiKeyId) {
77	    token = await resolveVaultSecret(apiKeyId);
78	  }
79	
80	  // initialize + tools/list via the MCP client, so the test reports the real tools.
81	  try {
82	    const result = await connectAndListTools(url, token);
83	    if (result.ok) {
84	      return NextResponse.json({
85	        ok: true,
86	        serverName: result.serverName,
87	        toolCount: result.tools?.length ?? 0,
88	        toolNames: (result.tools ?? []).map((t) => t.name).slice(0, 50),
89	      });
90	    }
91	    return NextResponse.json({ ok: false, error: result.error ?? "MCP connection failed." });
92	  } catch (err) {
93	    return NextResponse.json({ ok: false, error: err instanceof Error ? err.message : "MCP connection failed." });
94	  }
95	}

