154	export async function POST(req: NextRequest) {
155	  // Fail closed in production (middleware doesn't cover /api/*): never serve the
156	  // open demo path — which could spend env-resident provider keys unauthenticated.
157	  const prodBlock = prodFailClosed();
158	  if (prodBlock) return prodBlock;
159	
160	  // S-1: Auth FIRST — reject unauthenticated callers before buffering any body.
161	  const supabase = supabaseEnabled ? await getServerSupabase() : null;
162	  let userId: string | null = null;
163	  if (supabaseEnabled) {
164	    if (!supabase) return NextResponse.json({ ok: false, reason: "No Supabase client." }, { status: 500 });
165	    const {
166	      data: { user },
167	    } = await supabase.auth.getUser();
168	    if (!user) return NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 });
169	    userId = user.id;
170	  } else if (process.env.HERMES_API_URL) {
171	    // Demo mode but a live Aria runtime is configured — require a shared secret so
172	    // the proxy isn't an open relay to the upstream runtime.
173	    const secret = process.env.HERMES_PROXY_SECRET;
174	    if (!secret) return NextResponse.json({ ok: false, reason: "Proxy authentication not configured." }, { status: 503 });
175	    if ((req.headers.get("authorization") ?? "") !== `Bearer ${secret}`) {
176	      return NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 });
177	    }
178	  }
179	
180	  // S-2: Rate limit — 60 req/min, keyed to the authenticated principal (and IP),
181	  // applied right after identifying the caller and before buffering the body.
182	  const rl = checkRateLimit(rateLimitKey(req, "hermes-chat", userId), { windowMs: 60_000, max: 60 });
183	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
184	
185	  // Campaign context can carry a full campaign + candidate list — same shape/size posture
