  4	/**
  5	 * SSRF-safe URL validator for upstream HTTP proxies.
  6	 *
  7	 * Allows only http/https schemes and private/internal IPs commonly used for
  8	 * local Aria deployments. Blocks file/ftp/gopher, metadata endpoints, and
  9	 * ambiguous hostnames that could resolve to internal services.
 10	 */
 11	export function isAllowedHermesUrl(urlString: string): { ok: boolean; reason?: string } {
 12	  let url: URL;
 13	  try {
 14	    url = new URL(urlString);
 15	  } catch {
 16	    return { ok: false, reason: "Invalid URL." };
 17	  }
 18	
 19	  if (url.protocol !== "http:" && url.protocol !== "https:") {
 20	    return { ok: false, reason: "Only http/https schemes are allowed." };
 21	  }
 22	
 23	  const hostname = url.hostname.toLowerCase();
 24	
 25	  // Block metadata / link-local / broadcast / wildcard / cloud metadata addresses.
 26	  const blockedHostPatterns = [
 27	    /^169\.254\.\d+\.\d+$/, // link-local IPv4
 28	    /^127\.(?!0\.0\.1$)\d+\.\d+\.\d+$/, // loopback IPv4 except exact 127.0.0.1
 29	    /^0\.\d+\.\d+\.\d+$/, // current network
 30	    /^255\.\d+\.\d+\.\d+$/, // broadcast
 31	    /^::1$/, // loopback IPv6
 32	    /^::$/, // unspecified IPv6
 33	    /^fc00:/i, // unique local IPv6
 34	    /^fe80:/i, // link-local IPv6
 35	    /^ff00:/i, // multicast IPv6
 36	    /^metadata$/, // AWS / GCP metadata
 37	    /^metadata\.google\.internal$/,
 38	    /^instance-data$/,
 39	    /^169\.254\./,
 40	  ];
 41	  for (const pattern of blockedHostPatterns) {
 42	    if (pattern.test(hostname)) {
 43	      return { ok: false, reason: "Blocked host pattern (SSRF guard)." };
 44	    }
 45	  }
 46	
 47	  // Allow common local hostnames and private IP prefixes used for Aria.
 48	  const allowedHostPatterns = [
 49	    /^localhost$/,
 50	    /^127\.0\.0\.1$/,
 51	    /^hermes$/,
 52	    /^hermes-agent$/,
 53	    /^gateway$/,
 54	    /^host\.docker\.internal$/,
