 56	    /^172\.(1[6-9]|2\d|3[01])\.\d+\.\d+$/,
 57	    /^192\.168\.\d+\.\d+$/,
 58	  ];
 59	  const isAllowed = allowedHostPatterns.some((pattern) => pattern.test(hostname));
 60	  if (!isAllowed) {
