  1	// Anthropic tool-calling loop backed by registered MCP servers. This is what turns the
  2	// MCP registry into real capability: when MCP servers are configured, the model is given
  3	// their tools and can call them mid-conversation, with the app brokering each call to the
  4	// MCP server (server-side, with the vault token) and feeding the result back.
  5	//
  6	// Additive + safe by construction: callers only invoke this when there is at least one
  7	// resolved MCP server with tools; otherwise the normal single-shot completion path is
  8	// unchanged. Secrets never reach the client — the caller passes resolved server tokens
  9	// (looked up from the key vault server-side), never the raw key from the browser.
 10	
 11	import { callMcpTool, type McpTool } from "@/lib/mcp-client";
 12	import { CLOUD_ENDPOINT, type AiProviderSlug } from "@/lib/ai/provider";
 13	import { BUILTIN_WEB_URL, runWebTool } from "@/lib/ai/web-tools";
 14	import { BUILTIN_BROWSER_URL, runBrowserTool } from "@/lib/ai/browser-tools";
 15	
 16	const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
 17	
 18	export interface ResolvedMcpServer {
 19	  url: string;
 20	  token: string;
 21	  tools: McpTool[];
 22	  /** Optional workspace-scoped Tavily key for the in-process web_search tool. */
 23	  tavilyKey?: string;
 24	  /** Optional direct dispatcher for a stateful in-process tool set (e.g. a
 25	   *  per-request sourcing-tool runner that accumulates real candidates found
 26	   *  across calls). When present, execTool calls this instead of the URL-based
 27	   *  dispatch, so the caller can inspect that accumulated state after the loop
 28	   *  finishes rather than trusting the model to echo it back correctly. */
 29	  run?: (name: string, args: Record<string, unknown>) => Promise<{ ok: boolean; content?: unknown; error?: string }>;
 30	}
 31	
 32	/** One completed tool call, for callers that need the real results the loop saw
 33	 *  (not just the model's final prose summarizing them). */
 34	export interface ToolCallRecord {
 35	  name: string;
 36	  input: Record<string, unknown>;
 37	  output: { ok: boolean; content?: unknown; error?: string };
 38	}
 39	
 40	/**
 41	 * Execute one tool call. A server with a `run` override (a stateful in-process
 42	 * tool set) is dispatched directly; the built-in web-research and browser-research
 43	 * servers (the BUILTIN_WEB_URL / BUILTIN_BROWSER_URL sentinels) run in-process;
 44	 * everything else is brokered to the remote MCP server with its vault token.
 45	 * Same {ok, content, error} contract either way.
 46	 */
 47	async function execTool(
 48	  server: ResolvedMcpServer,
 49	  name: string,
 50	  args: Record<string, unknown>,
 51	): Promise<{ ok: boolean; content?: unknown; error?: string }> {
 52	  if (server.run) return server.run(name, args);
 53	  if (server.url === BUILTIN_WEB_URL) return runWebTool(name, args, { tavilyKey: server.tavilyKey });
 54	  if (server.url === BUILTIN_BROWSER_URL) return runBrowserTool(name, args);
 55	  return callMcpTool(server.url, server.token, name, args);
 56	}
 57	
 58	interface AnthropicToolDef {
 59	  name: string;
 60	  description: string;
 61	  input_schema: Record<string, unknown>;
 62	}
 63	
 64	/**
 65	 * Map resolved MCP servers' tools to Anthropic tool definitions, plus an index from
 66	 * tool name to the owning server. Pure (no I/O) so it is unit-testable. On a tool-name
 67	 * collision across servers, the first server wins (later duplicates are dropped).
 68	 */
 69	export function buildAnthropicToolDefs(servers: ResolvedMcpServer[]): {
 70	  toolDefs: AnthropicToolDef[];
 71	  owner: Map<string, ResolvedMcpServer>;
 72	} {
 73	  const toolDefs: AnthropicToolDef[] = [];
 74	  const owner = new Map<string, ResolvedMcpServer>();
 75	  for (const server of servers) {
 76	    for (const t of server.tools) {
 77	      if (!t.name || owner.has(t.name)) continue;
 78	      owner.set(t.name, server);
 79	      const schema =
 80	        t.inputSchema && typeof t.inputSchema === "object"
 81	          ? (t.inputSchema as Record<string, unknown>)
 82	          : { type: "object", properties: {} };
 83	      toolDefs.push({ name: t.name, description: t.description ?? "", input_schema: schema });
 84	    }
 85	  }
 86	  return { toolDefs, owner };
 87	}
 88	
 89	interface AnthropicContentBlock {
 90	  type: string;
 91	  text?: string;
 92	  id?: string;
 93	  name?: string;
 94	  input?: Record<string, unknown>;
 95	}
 96	
 97	interface AnthropicMessage {
 98	  role: "user" | "assistant";
 99	  content: string | unknown[];
100	}
101	
102	/** Collapse the model's text blocks into a single string. */
103	function textFrom(content: AnthropicContentBlock[]): string {
104	  return content
105	    .filter((b) => b.type === "text")
106	    .map((b) => b.text ?? "")
107	    .join("")
108	    .trim();
109	}
110	
111	/**
112	 * Run an Anthropic completion that may call MCP tools, looping until the model returns a
113	 * final answer or the round cap is hit. Returns the final text, or an error reason.
114	 */
115	export async function runAnthropicWithTools(args: {
116	  model: string;
117	  system: string;
118	  prompt: string;
119	  key: string;
120	  servers: ResolvedMcpServer[];
121	  maxRounds?: number;
122	  timeoutMs?: number;
123	}): Promise<{ ok: boolean; text?: string; reason?: string; toolCalls: ToolCallRecord[] }> {
124	  const { model, system, prompt, key, servers } = args;
125	  const maxRounds = args.maxRounds ?? 4;
126	  const timeoutMs = args.timeoutMs ?? 30_000;
127	  const toolCalls: ToolCallRecord[] = [];
128	
129	  const { toolDefs, owner } = buildAnthropicToolDefs(servers);
130	  if (!toolDefs.length) return { ok: false, reason: "No MCP tools available.", toolCalls };
131	
132	  const messages: AnthropicMessage[] = [{ role: "user", content: prompt }];
133	
134	  for (let round = 0; round < maxRounds; round++) {
135	    let res: Response;
136	    try {
137	      res = await fetch(ANTHROPIC_URL, {
138	        method: "POST",
139	        headers: { "content-type": "application/json", "x-api-key": key, "anthropic-version": "2023-06-01" },
140	        body: JSON.stringify({ model, max_tokens: 4096, system, messages, tools: toolDefs }),
141	        redirect: "manual",
142	        signal: AbortSignal.timeout(timeoutMs),
143	      });
144	    } catch (err) {
145	      return { ok: false, reason: err instanceof Error ? err.message : "Network error.", toolCalls };
146	    }
147	    if (!res.ok) return { ok: false, reason: `Upstream error ${res.status}`, toolCalls };
148	
149	    const json = (await res.json().catch(() => null)) as
150	      | { content?: AnthropicContentBlock[]; stop_reason?: string }
151	      | null;
152	    const content = json?.content;
153	    if (!content) return { ok: false, reason: "Empty response from provider.", toolCalls };
154	
155	    const toolUses = content.filter((b) => b.type === "tool_use");
156	    // No tool call (or model is done) → final answer.
157	    if (json?.stop_reason !== "tool_use" || toolUses.length === 0) {
158	      return { ok: true, text: textFrom(content), toolCalls };
159	    }
160	
161	    // Echo the assistant turn, then run each requested tool and return the results.
162	    messages.push({ role: "assistant", content });
163	    const toolResults: unknown[] = [];
164	    for (const tu of toolUses) {
165	      const server = tu.name ? owner.get(tu.name) : undefined;
166	      let resultText = "Tool not available.";
167	      let out: { ok: boolean; content?: unknown; error?: string } = { ok: false, error: "Tool not available." };
168	      if (server && tu.name) {
169	        out = await execTool(server, tu.name, tu.input ?? {});
170	        resultText = out.ok
171	          ? JSON.stringify(out.content ?? "").slice(0, 4000)
172	          : `Error: ${out.error ?? "tool failed"}`;
173	      }
174	      if (tu.name) toolCalls.push({ name: tu.name, input: tu.input ?? {}, output: out });
175	      toolResults.push({ type: "tool_result", tool_use_id: tu.id, content: resultText });
176	    }
177	    messages.push({ role: "user", content: toolResults });
178	  }
179	
180	  return { ok: false, reason: "Tool loop exceeded the round limit.", toolCalls };
181	}
