183	/* ------------------------------------------------------------------------- *
184	 * OpenAI-compatible variant (OpenAI / Groq / xAI / Mistral). Same loop, the  *
185	 * chat/completions tool-call wire format.                                    *
186	 * ------------------------------------------------------------------------- */
187	
188	interface OpenAiToolDef {
189	  type: "function";
190	  function: { name: string; description: string; parameters: Record<string, unknown> };
191	}
192	
193	/** Map resolved MCP tools to OpenAI-compatible tool definitions (pure, testable). */
194	export function buildOpenAiToolDefs(servers: ResolvedMcpServer[]): {
195	  toolDefs: OpenAiToolDef[];
196	  owner: Map<string, ResolvedMcpServer>;
197	} {
198	  const toolDefs: OpenAiToolDef[] = [];
199	  const owner = new Map<string, ResolvedMcpServer>();
200	  for (const server of servers) {
201	    for (const t of server.tools) {
202	      if (!t.name || owner.has(t.name)) continue;
203	      owner.set(t.name, server);
204	      const parameters =
205	        t.inputSchema && typeof t.inputSchema === "object"
206	          ? (t.inputSchema as Record<string, unknown>)
207	          : { type: "object", properties: {} };
208	      toolDefs.push({ type: "function", function: { name: t.name, description: t.description ?? "", parameters } });
209	    }
210	  }
211	  return { toolDefs, owner };
212	}
213	
214	interface OpenAiToolCall {
215	  id?: string;
216	  type?: string;
217	  function?: { name?: string; arguments?: string };
218	}
219	
220	interface OpenAiMessage {
221	  role: string;
222	  content?: string | null;
223	  tool_calls?: OpenAiToolCall[];
224	  tool_call_id?: string;
225	}
226	
227	/** OpenAI-compatible completion that may call MCP tools, looping to a final answer. */
228	export async function runOpenAiWithTools(args: {
229	  provider: AiProviderSlug;
230	  model: string;
231	  system: string;
232	  prompt: string;
233	  key: string;
234	  servers: ResolvedMcpServer[];
235	  maxRounds?: number;
236	  timeoutMs?: number;
237	}): Promise<{ ok: boolean; text?: string; reason?: string; toolCalls: ToolCallRecord[] }> {
238	  const { provider, model, system, prompt, key, servers } = args;
239	  const maxRounds = args.maxRounds ?? 4;
240	  const timeoutMs = args.timeoutMs ?? 30_000;
241	  const url = CLOUD_ENDPOINT[provider];
242	  const toolCallLog: ToolCallRecord[] = [];
243	
244	  const { toolDefs, owner } = buildOpenAiToolDefs(servers);
245	  if (!toolDefs.length) return { ok: false, reason: "No MCP tools available.", toolCalls: toolCallLog };
246	
247	  const messages: OpenAiMessage[] = [
248	    { role: "system", content: system },
249	    { role: "user", content: prompt },
250	  ];
251	
252	  for (let round = 0; round < maxRounds; round++) {
253	    let res: Response;
254	    try {
255	      res = await fetch(url, {
256	        method: "POST",
257	        headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
258	        body: JSON.stringify({ model, messages, tools: toolDefs, stream: false }),
259	        redirect: "manual",
260	        signal: AbortSignal.timeout(timeoutMs),
261	      });
262	    } catch (err) {
263	      return { ok: false, reason: err instanceof Error ? err.message : "Network error.", toolCalls: toolCallLog };
264	    }
265	    if (!res.ok) return { ok: false, reason: `Upstream error ${res.status}`, toolCalls: toolCallLog };
266	
267	    const json = (await res.json().catch(() => null)) as
268	      | { choices?: { message?: OpenAiMessage; finish_reason?: string }[] }
269	      | null;
270	    const choice = json?.choices?.[0];
271	    const message = choice?.message;
272	    if (!message) return { ok: false, reason: "Empty response from provider.", toolCalls: toolCallLog };
273	
274	    const toolCalls = message.tool_calls ?? [];
275	    if (choice?.finish_reason !== "tool_calls" || toolCalls.length === 0) {
276	      return { ok: true, text: (message.content ?? "").trim(), toolCalls: toolCallLog };
277	    }
278	
279	    // Echo the assistant turn (carrying its tool_calls), then return each tool result.
280	    messages.push({ role: "assistant", content: message.content ?? "", tool_calls: toolCalls });

280	    messages.push({ role: "assistant", content: message.content ?? "", tool_calls: toolCalls });
281	    for (const tc of toolCalls) {
282	      const name = tc.function?.name;
283	      const server = name ? owner.get(name) : undefined;
284	      let resultText = "Tool not available.";
285	      let parsedArgs: Record<string, unknown> = {};
286	      let out: { ok: boolean; content?: unknown; error?: string } = { ok: false, error: "Tool not available." };
287	      if (server && name) {
288	        try {
289	          parsedArgs = JSON.parse(tc.function?.arguments || "{}") as Record<string, unknown>;
290	        } catch {
291	          parsedArgs = {};
292	        }
293	        out = await execTool(server, name, parsedArgs);
294	        resultText = out.ok ? JSON.stringify(out.content ?? "").slice(0, 4000) : `Error: ${out.error ?? "tool failed"}`;
295	      }
296	      if (name) toolCallLog.push({ name, input: parsedArgs, output: out });
297	      messages.push({ role: "tool", tool_call_id: tc.id, content: resultText });
298	    }
299	  }
300	
301	  return { ok: false, reason: "Tool loop exceeded the round limit.", toolCalls: toolCallLog };
