36	export async function resolveStoredDatabricksSecret(
37	  session: NonNullable<Awaited<ReturnType<typeof getServerSupabase>>>,
38	  apiKeyId: string | undefined,
39	  serviceClient = getServiceSupabase(),
40	): Promise<string | null> {
41	  if (!apiKeyId || !serviceClient) return null;
