 1	import { NextRequest, NextResponse } from "next/server";
 2	import { ZodSchema, ZodError } from "zod";
 3	
 4	/**
 5	 * Shared API input validation helper.
 6	 *
 7	 * - Rejects oversized bodies before buffering.
 8	 * - Parses JSON safely.
 9	 * - Validates the body against the provided Zod schema and returns a
10	 *   field-level 400 response on failure.
11	 */
12	export async function validateBody<T>(
13	  req: NextRequest,
14	  schema: ZodSchema<T>,
15	  { maxBytes = 32_000 }: { maxBytes?: number } = {},
16	): Promise<{ ok: true; data: T } | { ok: false; response: NextResponse }> {
17	  // Enforce the byte cap against actually-received bytes, not the client-controlled
18	  // Content-Length header (absent or spoofable → the old check was bypassable).
19	  const buf = await req.arrayBuffer();
20	  if (buf.byteLength > maxBytes) {
21	    return {
22	      ok: false,
23	      response: NextResponse.json({ ok: false, error: "Payload too large." }, { status: 413 }),
24	    };
25	  }
26	
27	  let raw: unknown;
28	  try {
29	    raw = JSON.parse(new TextDecoder().decode(buf));
30	  } catch {
31	    return {
32	      ok: false,
33	      response: NextResponse.json({ ok: false, error: "Invalid JSON body." }, { status: 400 }),
34	    };
35	  }
36	
37	  const parsed = schema.safeParse(raw);
38	  if (!parsed.success) {
39	    return {
40	      ok: false,
41	      response: NextResponse.json(
42	        {
43	          ok: false,
44	          error: "Validation failed.",
45	          issues: formatZodIssues(parsed.error),
46	        },
47	        { status: 400 },
48	      ),
49	    };
50	  }
51	
52	  return { ok: true, data: parsed.data };
53	}
54	
55	function formatZodIssues(error: ZodError): { path: string; message: string }[] {
56	  return error.issues.map((issue) => ({
57	    path: issue.path.length ? issue.path.join(".") : "root",
58	    message: issue.message,
59	  }));
60	}
